// Build Order: validate the order, check the pickup date, and calculate the total.
// The LLM never does the math or the calendar checks. This code does.
const input = $('When Executed by Another Workflow').first().json;
const menu = $input.all().map(i => i.json).filter(r => r.item); // skip the empty item from "Always Output Data"

const fail = (error) => [{ json: { ok: false, error } }];

// ---------- 1. Customer details ----------
// The contact number identifies the customer. If they're already in the customers table,
// use the saved full name instead of whatever the agent typed (e.g. "Juan" -> "Juan Dela Cruz").
const contact = String(input.contact || '').trim();
if (!contact) {
  return fail('Missing contact. Reuse it from earlier in this conversation; only ask the customer if they never gave it.');
}
const saved = $('Get Customer').all().map(i => i.json).find(r => r.contact === contact);
const customerName = (saved && saved.name) ? String(saved.name).trim() : String(input.customer_name || '').trim();
if (!customerName) {
  return fail('Missing customer_name for a new customer. Ask the customer for their full name.');
}

// ---------- 2. Items: must exist on today's menu ----------
// items arrives as a JSON string like [{"item":"Ube Ensaymada","qty":6}]
let items;
try {
  items = typeof input.items === 'string' ? JSON.parse(input.items) : input.items;
} catch (e) {
  return fail('items must be a JSON array like [{"item":"Ube Ensaymada","qty":6}]');
}
if (!Array.isArray(items) || items.length === 0) return fail('The order has no items.');

let total = 0;
const lines = [];
for (const it of items) {
  const name = String(it.item || '').toLowerCase().trim();
  const m = menu.find(r => String(r.item).toLowerCase().trim() === name);
  if (!m) return fail(`"${it.item}" is not available today.`);

  const qty = Number(it.qty);
  if (!Number.isInteger(qty) || qty <= 0 || qty > 200) {
    return fail(`Invalid quantity for ${m.item}.`);
  }
  total += m.price * qty;
  lines.push(`${qty} x ${m.item} @ ₱${m.price}`);
}

// ---------- 3. Pickup date: format, lead time, closed Mondays, store hours ----------
const raw = String(input.pickup_date || '').trim();
const d = raw.match(/^(\d{4}-\d{2}-\d{2})(?:[ T](\d{1,2}):(\d{2}))?$/);
if (!d) {
  return fail('pickup_date must be "YYYY-MM-DD" or "YYYY-MM-DD HH:MM" (24-hour), e.g. "2026-10-20 10:00". Convert the customer\'s words to this format.');
}

const tz = 'Asia/Manila';                                        // Philippine time, not server time
const day = DateTime.fromISO(d[1], { zone: tz });
if (!day.isValid) return fail(`"${d[1]}" is not a real date.`);

const today = DateTime.now().setZone(tz).startOf('day');
const fmt = (x) => x.toFormat('cccc, LLL d');                    // e.g. "Tuesday, Oct 20"
const skipMonday = (x) => (x.weekday === 1 ? x.plus({ days: 1 }) : x); // Luxon: 1 = Monday
const earliest = skipMonday(today.plus({ days: 1 }));

if (day < today.plus({ days: 1 })) {
  return fail(`Orders need at least 1 day lead time. The earliest pickup is ${fmt(earliest)}.`);
}
if (day.weekday === 1) {
  return fail(`${fmt(day)} is a Monday and the store is closed. Suggest ${fmt(day.plus({ days: 1 }))} instead.`);
}

let pickupTime = '';
if (d[2]) {
  const minutes = Number(d[2]) * 60 + Number(d[3]);
  if (minutes < 9 * 60 || minutes > 18 * 60) {
    return fail('Pickup time must be between 09:00 and 18:00.');
  }
  pickupTime = ` ${d[2].padStart(2, '0')}:${d[3]}`;
}

// ---------- 4. All good: return the validated order ----------
return [{
  json: {
    ok: true,
    confirm: input.confirm === true || input.confirm === 'true',
    customer_name: customerName,      // saved full name when we know the customer
    contact,
    items: lines.join('; '),
    total,
    pickup_date: d[1] + pickupTime,   // e.g. "2026-10-20 10:00" (sortable, saved to the table)
    pickup_day: fmt(day),             // e.g. "Tuesday, Oct 20" (for the agent to show the customer)
    status: 'new',
  },
}];
